package com.bankease.repository; import com.bankease.entity.Account; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import java.util.*; public interface AccountRepository extends JpaRepository<Account,Long>{Optional<Account> findByAccountNumber(String accountNumber); List<Account> findByUserId(Long userId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select a from Account a where a.accountNumber=:number") Optional<Account> findForUpdate(String number);}